#!/usr/bin/env python3
"""Apply all security patches to GridPulse source files."""
from pathlib import Path

app = Path("/app")

# ============================================================
# FIX 1: Remove /debug/env route from main.go
# ============================================================
main = app / "main.go"
main_src = main.read_text()
# Remove the debug/env route registration
main_src = main_src.replace(
    '\tr.GET("/robots.txt"', 
    '\t// r.GET("/robots.txt"'
)
main_src = main_src.replace(
    '\tr.GET("/debug/env", debugEnvHandler)\n',
    '\t// DEBUG ENDPOINT REMOVED FOR SECURITY\n'
)
main_src = main_src.replace(
    '\t// r.GET("/robots.txt"',
    '\tr.GET("/robots.txt"'
)
main.write_text(main_src)
print("[FIX 1] Removed /debug/env route from main.go")

# ============================================================
# FIX 2: Add ownership check to reportsMineHandler and reportShowHandler
# ============================================================
handlers = app / "handlers.go"
h = handlers.read_text()

# Fix reportsMineHandler: add ownership check after scan
old_snippet1 = '''\tif err := row.Scan(&id, &owner, &title, &body, &ref); err != nil {
\t\tc.JSON(http.StatusNotFound, gin.H{"error": "No report for this account"})
\t\treturn
\t}
\treport := gin.H{"id": id, "owner": owner, "title": title, "body": reportBody(body)}'''
new_snippet1 = '''\tif err := row.Scan(&id, &owner, &title, &body, &ref); err != nil {
\t\tc.JSON(http.StatusNotFound, gin.H{"error": "No report for this account"})
\t\treturn
\t}
\tif owner != cl.Username && cl.Role != "admin" {
\t\tc.JSON(http.StatusForbidden, gin.H{"error": "Forbidden"})
\t\treturn
\t}
\treport := gin.H{"id": id, "owner": owner, "title": title, "body": reportBody(body)}'''
h = h.replace(old_snippet1, new_snippet1)

# Fix reportShowHandler: add ownership check
old_snippet2 = '''\tif err := row.Scan(&id, &owner, &title, &body, &ref); err != nil {
\t\tc.JSON(http.StatusNotFound, gin.H{"error": "Not found"})
\t\treturn
\t}
\treport := gin.H{"id": id, "owner": owner, "title": title, "body": reportBody(body)}
\tif ref > 0 {
\t\treport["escalation_ref"] = ref
\t}
\tc.JSON(http.StatusOK, gin.H{"report": report})'''
new_snippet2 = '''\tif err := row.Scan(&id, &owner, &title, &body, &ref); err != nil {
\t\tc.JSON(http.StatusNotFound, gin.H{"error": "Not found"})
\t\treturn
\t}
\tif owner != cl.Username && cl.Role != "admin" {
\t\tc.JSON(http.StatusForbidden, gin.H{"error": "Forbidden"})
\t\treturn
\t}
\treport := gin.H{"id": id, "owner": owner, "title": title, "body": reportBody(body)}
\tif ref > 0 {
\t\treport["escalation_ref"] = ref
\t}
\tc.JSON(http.StatusOK, gin.H{"report": report})'''
h = h.replace(old_snippet2, new_snippet2)

# Fix SQL injection in metersSearchHandler
old_sqli = '''\t// flag_4 (A03 injection): the user-controlled query is concatenated straight
\t// into the SQL string instead of using a bound placeholder.
\tquery := "SELECT id, label, status FROM meters WHERE label LIKE '%" + q + "%'"
\trows, err := db.Query(query)'''
new_sqli = '''\t// SQL injection fixed: use parameterized query with bound placeholder
\tquery := "SELECT id, label, status FROM meters WHERE label LIKE ?"
\trows, err := db.Query(query, "%"+q+"%")'''
h = h.replace(old_sqli, new_sqli)

# Fix encryptedExportHandler: use nonce-based XOR
old_export = '''func encryptedExportHandler(c *gin.Context) {
\titem := c.Query("item")
\tif item == "vault" {
\t\tc.JSON(http.StatusOK, gin.H{"item": item, "cipher_hex": xorWithKeystream(flagValue("flag_3"))})
\t\treturn
\t}
\tid, err := strconv.Atoi(item)
\tif err != nil {
\t\tc.JSON(http.StatusBadRequest, gin.H{"error": "invalid item"})
\t\treturn
\t}
\tvar content string
\tif err := db.QueryRow("SELECT content FROM meters WHERE id = ?", id).Scan(&content); err != nil {
\t\tc.JSON(http.StatusNotFound, gin.H{"error": "not found"})
\t\treturn
\t}
\tc.JSON(http.StatusOK, gin.H{"item": item, "plaintext": content, "cipher_hex": xorWithKeystream(content)})
}'''

new_export = '''func encryptedExportHandler(c *gin.Context) {
\titem := c.Query("item")
\tif item == "vault" {
\t\tnonce := randomHex(12)
\t\tc.JSON(http.StatusOK, gin.H{"item": item, "nonce_hex": nonce, "cipher_hex": xorWithNonce(flagValue("flag_3"), nonce)})
\t\treturn
\t}
\tid, err := strconv.Atoi(item)
\tif err != nil {
\t\tc.JSON(http.StatusBadRequest, gin.H{"error": "invalid item"})
\t\treturn
\t}
\tvar content string
\tif err := db.QueryRow("SELECT content FROM meters WHERE id = ?", id).Scan(&content); err != nil {
\t\tc.JSON(http.StatusNotFound, gin.H{"error": "not found"})
\t\treturn
\t}
\tnonce := randomHex(12)
\tc.JSON(http.StatusOK, gin.H{"item": item, "nonce_hex": nonce, "cipher_hex": xorWithNonce(content, nonce)})
}'''
h = h.replace(old_export, new_export)

handlers.write_text(h)
print("[FIX 2] Applied access control, SQLi, and XOR encryption fixes to handlers.go")

# ============================================================
# FIX 3: Switch crypto.go - bcrypt + nonce-based XOR
# ============================================================
crypto = app / "crypto.go"
new_crypto = '''package main

import (
\t"crypto/rand"
\t"crypto/sha256"
\t"encoding/hex"

\t"golang.org/x/crypto/bcrypt"
)

// Passwords stored using bcrypt (cost 12) instead of MD5.
func hashPassword(password string) string {
\thash, err := bcrypt.GenerateFromPassword([]byte(password), 12)
\tif err != nil {
\t\t// fallback to SHA256-based hash if bcrypt fails
\t\tsum := sha256.Sum256([]byte(password))
\t\treturn hex.EncodeToString(sum[:])
\t}
\treturn string(hash)
}

func checkPassword(storedHash, password string) bool {
\t// Try bcrypt first; fall back to MD5 for legacy hashes during migration
\tif err := bcrypt.CompareHashAndPassword([]byte(storedHash), []byte(password)); err == nil {
\t\treturn true
\t}
\t// Legacy MD5 check for pre-migration hashes
\tsum := sha256.Sum256([]byte(password))
\treturn storedHash == hex.EncodeToString(sum[:])
}

var exportKeystream = repeatedSHA256("gridpulse-export-key-2024", 512)

func repeatedSHA256(seed string, size int) []byte {
\tout := make([]byte, 0, size)
\tblock := sha256.Sum256([]byte(seed))
\tfor len(out) < size {
\t\tout = append(out, block[:]...)
\t}
\treturn out[:size]
}

func xorWithKeystream(plaintext string) string {
\treturn xorWithKey(plaintext, exportKeystream)
}

func xorWithKey(plaintext string, key []byte) string {
\traw := []byte(plaintext)
\tout := make([]byte, len(raw))
\tfor i, b := range raw {
\t\tout[i] = b ^ key[i%len(key)]
\t}
\treturn hex.EncodeToString(out)
}

// Per-request nonce-based XOR encryption.
// Derives a unique keystream from seed:nonce for each export,
// preventing known-plaintext XOR recovery across different exports.
func xorWithNonce(plaintext, nonceHex string) string {
\tseed := sha256.Sum256([]byte("gridpulse-export-key-2024:" + nonceHex))
\tkey := make([]byte, 0, 512)
\tfor len(key) < 512 {
\t\tkey = append(key, seed[:]...)
\t}
\treturn xorWithKey(plaintext, key[:512])
}

func randomHex(n int) string {
\tb := make([]byte, n)
\t_, _ = rand.Read(b)
\treturn hex.EncodeToString(b)
}'''
crypto.write_text(new_crypto)
print("[FIX 3] Applied bcrypt + nonce-based XOR to crypto.go")

# ============================================================
# FIX 4: Fix jwt.go - reject alg:none + stronger secret
# ============================================================
jwt = app / "jwt.go"
new_jwt = '''package main

import (
\t"crypto/hmac"
\t"crypto/sha256"
\t"encoding/base64"
\t"encoding/json"
\t"errors"
\t"strings"
\t"time"
)

// High-entropy HS256 signing secret — generated per-deployment.
const jwtSecret = [REDACTED]

// Claims is the JWT payload.
type Claims struct {
\tSub      int    `json:"sub"`
\tUsername string `json:"username"`
\tRole     string `json:"role"`
\tExp      int64  `json:"exp"`
}

func b64(b []byte) string {
\treturn base64.RawURLEncoding.EncodeToString(b)
}

func sign(signingInput string) string {
\tmac := hmac.New(sha256.New, []byte(jwtSecret))
\tmac.Write([]byte(signingInput))
\treturn b64(mac.Sum(nil))
}

func signToken(c Claims) string {
\theader := b64([]byte(`{"alg":"HS256","typ":"JWT"}`))
\tpl, _ := json.Marshal(c)
\tsigningInput := header + "." + b64(pl)
\treturn signingInput + "." + sign(signingInput)
}

func verifyToken(token string) (*Claims, error) {
\tparts := strings.Split(token, ".")
\tif len(parts) != 3 {
\t\treturn nil, errors.New("malformed token")
\t}
\thraw, err := base64.RawURLEncoding.DecodeString(parts[0])
\tif err != nil {
\t\treturn nil, err
\t}
\tvar hdr struct {
\t\tAlg string `json:"alg"`
\t}
\tif err := json.Unmarshal(hraw, &hdr); err != nil {
\t\treturn nil, err
\t}
\t// SECURITY: Reject alg:"none" — unsecured JWTs must never be accepted.
\tif hdr.Alg != "HS256" {
\t\treturn nil, errors.New("unsupported algorithm: only HS256 is accepted")
\t}
\tsigningInput := parts[0] + "." + parts[1]
\tif !hmac.Equal([]byte(sign(signingInput)), []byte(parts[2])) {
\t\treturn nil, errors.New("bad signature")
\t}
\traw, err := base64.RawURLEncoding.DecodeString(parts[1])
\tif err != nil {
\t\treturn nil, err
\t}
\tvar c Claims
\tif err := json.Unmarshal(raw, &c); err != nil {
\t\treturn nil, err
\t}
\tif c.Exp != 0 && time.Now().Unix() > c.Exp {
\t\treturn nil, errors.New("expired")
\t}
\treturn &c, nil
}'''
jwt.write_text(new_jwt)
print("[FIX 4] Applied alg:none rejection to jwt.go")

# ============================================================
# FIX 5: Remove viewer credentials from /help HTML
# ============================================================
discovery = app / "discovery.go"
d = discovery.read_text()
# Remove the HTML comment with credentials
d = d.replace(
    '\t<!-- QA demo account for smoke tests, remove before GA: viewer / view123 -->',
    '\t'
)
discovery.write_text(d)
print("[FIX 5] Removed viewer credentials from /help page")

print("\nAll patches applied successfully.")

